// Takes `percent` off an integer amount in minor units, rounding to the nearest unit (halves round up).
export function applyDiscount(amount: number, percent: number): number {
  if (!Number.isInteger(amount) || amount < 0) throw new RangeError(`invalid amount: ${amount}`);
  if (typeof percent !== 'number' || Number.isNaN(percent) || percent < 0 || percent > 100) {
    throw new RangeError(`invalid percent: ${percent}`);
  }
  return Math.round((amount * (100 - percent)) / 100);
}

