import assert from 'node:assert/strict';
import { test } from 'node:test';
import { applyDiscount } from '../src/discount.ts';

test('takes the percent off the amount', () => {
  assert.equal(applyDiscount(1000, 10), 900);
  assert.equal(applyDiscount(3699, 0), 3699);
  assert.equal(applyDiscount(1000, 100), 0);
});

test('rounds to the nearest minor unit, halves up', () => {
  assert.equal(applyDiscount(999, 10), 899); // 899.1 -> 899
  assert.equal(applyDiscount(1005, 10), 905); // 904.5 -> 905
  assert.equal(applyDiscount(1, 50), 1); // 0.5 -> 1
});

test('rejects invalid amounts and percents', () => {
  assert.throws(() => applyDiscount(-1, 10), RangeError);
  assert.throws(() => applyDiscount(10.5, 10), RangeError);
  assert.throws(() => applyDiscount(100, -1), RangeError);
  assert.throws(() => applyDiscount(100, 101), RangeError);
});

